<div class="modal fade" id="account-password-modal" tabindex="-1" role="dialog" aria-labelledby="account-password-title" aria-hidden="true"><div class="modal-dialog" role="document"><div class="modal-content"><div class="modal-header"><h5 class="modal-title" id="account-password-title">Password akun klien</h5><button type="button" class="close" data-dismiss="modal" aria-label="Tutup"><span>&times;</span></button></div><div class="modal-body"><div class="form-group"><label for="account-password-pin">PIN admin</label><input type="password" class="form-control" id="account-password-pin" autocomplete="off"></div><div id="account-password-result" class="d-none"><label>Username</label><div class="font-weight-bold mb-2" id="account-password-username"></div><label>Password</label><div class="input-group"><input type="text" class="form-control" id="account-password-value" readonly><div class="input-group-append"><button class="btn btn-outline-secondary" type="button" id="copy-account-password">Salin</button></div></div></div><div class="small text-muted mt-2">Password tidak disimpan di log dan hanya ditampilkan setelah validasi PIN.</div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-dismiss="modal">Tutup</button><button type="button" class="btn btn-primary" id="confirm-account-password">Tampilkan password</button></div></div></div></div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/toastr.js/latest/toastr.min.js"></script>
<script>
$(function(){
    let currentAccountId=0;
    const revealUrl='<?= base_url('admin/portal-sso-clients/accounts/' . rawurlencode($client['app_code']) . '/reveal') ?>';
    const updateToken=token=>{if(token)$('input[name="form_token"]').val(token);};
    let picFilter='all';
    function filterAccounts(){const query=String($('#account-search').val()||'').toLowerCase();let shown=0;$('#client-account-table tbody tr').each(function(){const $row=$(this),matchesText=String($row.data('search')||'').includes(query),assigned=String($row.data('pic-assigned'))==='1',matchesPic=picFilter==='all'||(picFilter==='assigned'&&assigned)||(picFilter==='empty'&&!assigned),visible=matchesText&&matchesPic;$row.toggle(visible);if(visible)shown++;});$('#account-result-count').text(shown+' akun ditampilkan');}
    $('#account-search').on('input',filterAccounts);$('.psa-filter').on('click',function(){picFilter=$(this).data('filter');$('.psa-filter').removeClass('active');$(this).addClass('active');filterAccounts();});filterAccounts();
    $('.pic-picker').on('change',function(){const parts=String($(this).val()||'').split(':');const $form=$(this).closest('form');$form.find('[name="pic_auth_source"]').val(parts.length===2?parts[0]:'');$form.find('[name="pic_user_id"]').val(parts.length===2?parts[1]:'0');});
    $('.delete-client-account').on('submit',function(event){if(!window.confirm('Hapus akun klien ini?'))event.preventDefault();});
    $('.reveal-account-password').on('click',function(){currentAccountId=$(this).data('account-id');$('#account-password-pin').val('');$('#account-password-result').addClass('d-none');$('#account-password-value,#account-password-username').val('').text('');$('#account-password-modal').modal('show');});
    $('#confirm-account-password').on('click',function(){const $button=$(this);$button.prop('disabled',true);$.ajax({url:revealUrl+'/'+encodeURIComponent(currentAccountId),type:'POST',data:{form_token:$('input[name="form_token"]').first().val(),pin:$('#account-password-pin').val()},dataType:'json'}).done(function(res){updateToken(res.data&&res.data.form_token);if(!res.status){toastr.error(res.message);return;}$('#account-password-username').text(res.data.username);$('#account-password-value').val(res.data.password);$('#account-password-result').removeClass('d-none');$('#account-password-pin').val('');}).fail(function(){toastr.error('Server tidak merespons saat membuka password.');}).always(function(){$button.prop('disabled',false);});});
    $('#copy-account-password').on('click',function(){const field=document.getElementById('account-password-value');field.select();document.execCommand('copy');toastr.success('Password disalin.');});
    $('#account-password-modal').on('hidden.bs.modal',function(){$('#account-password-pin,#account-password-value,#account-password-username').val('').text('');$('#account-password-result').addClass('d-none');currentAccountId=0;});
});
</script>
